  let func = FunctionDef {
    name: "get_value",
    params: [],
    return_type: "Int",
    body: "42"
  }
  let result = convert_function_def(func)
  result.contains("func get_value() i32")

function test_function_single_param(): Bool =
  let func = FunctionDef {
    name: "double",
    params: ["x: Int"],
    return_type: "Int",
    body: "x * 2"
  }
  let result = convert_function_def(func)
  result.contains("func double(x i32) i32")

function test_function_multiple_params(): Bool =
  let func = FunctionDef {
    name: "concat",
    params: ["a: String", "b: String"],
    return_type: "String",
    body: "a + b"
  }
