// ==========================================
// FV-Julia 성능 분석기
// ==========================================

type PerformanceIssue struct {
	severity string // "CRITICAL", "HIGH", "MEDIUM", "LOW"
	location string
	problem  string
	impact   string
	fix      string
}

var issues []PerformanceIssue

// ==========================================
// 1. O(n²) 알고리즘 탐지
// ==========================================

func analyzeNestedLoops() {
	fmt.Println("[ANALYSIS] Nested Loops (O(n²) detection)")
	fmt.Println("─────────────────────────────────────────")

	// string_split 함수: O(n*m) 복잡도
	issues = append(issues, PerformanceIssue{
		severity: "MEDIUM",
		location: "stdlib/string.fl:225-242",
		problem:  "string_split() uses nested while loops (separator search in each iteration)",
		impact:   "O(n*m) where n=string length, m=separator length. For 1000-char string: ~1M operations",
		fix:      "Use built-in split or implement Boyer-Moore algorithm for O(n+m)",
	})

	// dict_remove 함수: O(n²) 배열 복사
	issues = append(issues, PerformanceIssue{
		severity: "HIGH",
		location: "stdlib/collections.fl:336-346",
		problem:  "dict_remove() rebuilds entire array for each removal (array concatenation)",
		impact:   "O(n²) when removing multiple items. Removing 100 items from 1000-item dict: ~500K operations",
		fix:      "Use index-based removal or linked list, or mark-and-sweep approach",
	})

	// array_contains: O(n) linear search
	issues = append(issues, PerformanceIssue{
		severity: "LOW",
		location: "stdlib/collections.fl:64-73",
		problem:  "array_contains() linear search through entire array",
		impact:   "O(n) per search. No indexing. Fine for small arrays (<1000), bad for large.",
		fix:      "Use hash set for O(1) lookup if used frequently",
	})

	// string_index_of: O(n*m) naive search
	issues = append(issues, PerformanceIssue{
		severity: "MEDIUM",
		location: "compiler/main.fv:759-775",
		problem:  "string_index_of() naive substring search (character-by-character comparison)",
		impact:   "O(n*m) where n=haystack length, m=needle length. String 10K chars, pattern 100 chars: ~1M ops",
		fix:      "Implement KMP or use built-in indexOf",
	})

	for i, issue := range issues {
		if strings.Contains(issue.location, "O(n²)") || strings.Contains(issue.problem, "nested") {
			fmt.Printf("%d. [%s] %s\n", i+1, issue.severity, issue.problem)
			fmt.Printf("   Location: %s\n", issue.location)
			fmt.Printf("   Impact: %s\n", issue.impact)
			fmt.Println()
		}
	}
}

// ==========================================
// 2. 메모리 사용 패턴 분석
// ==========================================

func analyzeMemoryPatterns() {
	fmt.Println("[ANALYSIS] Memory Usage Patterns")
	fmt.Println("─────────────────────────────────────────")

	// 임시 배열 생성
	issues = append(issues, PerformanceIssue{
		severity: "MEDIUM",
		location: "stdlib/string.fl:57-71 (to_uppercase)",
		problem:  "string_uppercase() creates new string char-by-char (immutable string concatenation)",
		impact:   "For 10K string: creates 10K intermediate strings. Memory spike: O(n²)",
		fix:      "Use string builder or character array, then join once",
	})

	// 파라미터 복사
	issues = append(issues, PerformanceIssue{
		severity: "LOW",
		location: "stdlib/collections.fl (all functions)",
		problem:  "All array/dict functions receive copies of data (pass-by-value semantics)",
		impact:   "For 1M-element array: copies entire array on each call",
		fix:      "Use pass-by-reference if language supports, or return new structures",
	})

	for i, issue := range issues {
		if strings.Contains(issue.problem, "Memory") || strings.Contains(issue.problem, "creates") {
			fmt.Printf("%d. [%s] %s\n", i+1, issue.severity, issue.problem)
