import "strings"

func joinStrings(s []string) string {
	return strings.Join(s, "")
}

func sqrtWithoutGuard(x float64) float64 {
	if x == 0 {
		return 0
	}
	guess := x
	for i := 0; i < 10; i++ {
		guess = (guess + x/guess) / 2
	}
	return guess
}

func sqrtWithGuard(x float64) float64 {
	if x <= 0 {
		return 0
	}
	if x == 1 {
		return 1
	}
	guess := x / 2
	for i := 0; i < 10; i++ {
		if guess == 0 {
			return 0
		}
		guess = (guess + x/guess) / 2
	}
	return guess
}

func checkType(t string) string {
	return "checked:" + t
}

func simpleSplit(s, sep string) []string {
	parts := strings.Split(s, sep)
	return parts
}

func optimizedSplit(s, sep string) []string {
	parts := []string{}
	start := 0
	for i := 0; i <= len(s)-len(sep); i++ {
		if s[i:i+len(sep)] == sep {
			parts = append(parts, s[start:i])
			start = i + len(sep)
			i = start - 1
		}
	}
	parts = append(parts, s[start:])
	return parts
}

func lexerMultiPass(source string) []string {
	tokens := strings.Fields(source)
	return tokens
}

func lexerSinglePass(source string) []string {
	tokens := []string{}
	current := ""
	for _, ch := range source {
		if ch == ' ' {
			if current != "" {
				tokens = append(tokens, current)
				current = ""
			}
		} else {
			current += string(ch)
		}
	}
	if current != "" {
		tokens = append(tokens, current)
	}
	return tokens
}

func parseWithArraySlice(tokens []string) []string {
	return tokens[10:50]
}

func parseWithIndexRange(tokens []string) []string {
	result := []string{}
	for i := 10; i < 50 && i < len(tokens); i++ {
		result = append(result, tokens[i])
	}
	return result
}

func codegenWithConcat(n int) string {
	result := ""
	for i := 0; i < n; i++ {
		result = result + "stmt_" + fmt.Sprintf("%d", i) + ";\n"
	}
	return result
}

func codegenWithBuffer(n int) string {
	buffer := []string{}
	for i := 0; i < n; i++ {
		buffer = append(buffer, "stmt_"+fmt.Sprintf("%d", i)+";")
	}
	return strings.Join(buffer, "\n")
}

func quicksortStandard(arr []int, low, high int) {
	if low < high {
		pi := partitionStandard(arr, low, high)
		quicksortStandard(arr, low, pi-1)
		quicksortStandard(arr, pi+1, high)
	}
}

func partitionStandard(arr []int, low, high int) int {
	pivot := arr[high]
	i := low - 1
	for j := low; j < high; j++ {
		if arr[j] < pivot {
			i++
			arr[i], arr[j] = arr[j], arr[i]
		}
	}
	arr[i+1], arr[high] = arr[high], arr[i+1]
	return i + 1
}

func quicksort3Way(arr []int, low, high int) {
	if low < high {
		partition3Way(arr, low, high)
	}
}

func partition3Way(arr []int, low, high int) {
	pivot := arr[high]
	lt := low
	eq := low
	gt := high - 1

	for eq <= gt {
		if arr[eq] < pivot {
			arr[lt], arr[eq] = arr[eq], arr[lt]
			lt++
			eq++
		} else if arr[eq] == pivot {
			eq++
		} else {
			arr[eq], arr[gt] = arr[gt], arr[eq]
			gt--
		}
	}

	arr[eq], arr[high] = arr[high], arr[eq]
}

